impl MtlSm50ShaderArgument {
    /// Argument buffer index for this binding's type and slot (`GetArgumentIndex`).
    #[must_use]
    pub const fn argument_index(&self) -> u32 {
        get_argument_index(self.r#type, self.sm50_binding_slot)
    }
}

impl Sm50IaInputElement {
    pub const STEP_FUNCTION_SHIFT: u32 = 0;
    pub const STEP_FUNCTION_WIDTH: u32 = 1;
    pub const STEP_RATE_SHIFT: u32 = 1;
    pub const STEP_RATE_WIDTH: u32 = 31;

    /// Packs `step_function` (bit 0) and `step_rate` (bits 1..32) LSB-first.
    #[must_use]
    pub const fn pack_step(step_function: u32, step_rate: u32) -> u32 {
        (step_function & 1) | (step_rate << 1)
    }

    /// Creates an input element with `step_function` and `step_rate` packed LSB-first into `bits`.
    #[must_use]
    pub const fn new(
        reg: u32,
        slot: u32,
        aligned_byte_offset: u32,
        format: u32,
        step_function: u32,
        step_rate: u32,
    ) -> Self {
        Self {
            reg,
            slot,
            aligned_byte_offset,
            format,
            bits: Self::pack_step(step_function, step_rate),
        }
    }

    /// 0 per vertex, 1 per instance.
    #[must_use]
    pub const fn step_function(&self) -> u32 {
        self.bits & 1
    }

    /// Instance data step rate (bits 1..32).
    #[must_use]
    pub const fn step_rate(&self) -> u32 {
        self.bits >> 1
    }
}

/// Argument buffer index for `binding_type` (`SM50_BINDING_*`) and `slot` (`GetArgumentIndex`).
#[must_use]
pub const fn get_argument_index(binding_type: u32, slot: u32) -> u32 {
    match binding_type {
        SM50_BINDING_CONSTANT_BUFFER | SM50_BINDING_SAMPLER => slot,
        SM50_BINDING_SRV => slot + 16,
        SM50_BINDING_UAV => slot + 16 + 128,
        _ => u32::MAX,
    }
}

/// Reads `error`'s text into an owned [`String`] (`SM50GetErrorMessageString`), without freeing it.
///
/// # Safety
///
/// `error` must be a live `sm50_error_t` handle returned by an `SM50*` function (or `0` when the
/// linked `SM50GetErrorMessage` accepts a null handle).
#[must_use]
pub unsafe fn error_message(error: u64) -> String {
    let mut buf = vec![0_u8; 256];
    // SAFETY: `buf` is a writable 256-byte buffer and `error` satisfies the caller's contract.
    let size = unsafe { SM50GetErrorMessage(error, buf.as_mut_ptr().cast::<c_char>(), buf.len()) };
    buf.truncate(size.min(buf.len()));
    String::from_utf8(buf).unwrap_or_else(|e| String::from_utf8_lossy(e.as_bytes()).into_owned())
}

